#!/usr/bin/env bash
set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required.' >&2; exit 1; }
node <<'AF_THOMSON_NEUTRAL_PATCH'
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/components/simulation/AtomicModelsCanvas.tsx": "'use client';\nimport { useRef, useEffect, useCallback, useState } from 'react';\nimport {\n  AtomicParams, AtomicModel,\n  generateThomsonElectrons, updateThomsonElectrons,\n  createAlphaParticle, updateAlphaParticle,\n  bohrEnergy, bohrRadius, bohrVelocity, transitionWavelength,\n  wavelengthToRGB, generateOrbitalSlice, radialDistribution,\n  type ThomsonElectron, type ScatteringParticle,\n} from '@/lib/physics/atomicModels';\nimport './atomic-models.css';\nimport {viewZoom} from '@/lib/physics/bohrWorkbench';\nimport {BohrRadiationLab} from './BohrRadiationLab';\n\ninterface Props {\n  params: AtomicParams;\n  isRunning: boolean;\n  isPaused: boolean;\n  onModelChange?: (model:AtomicModel)=>void;\n  onSpeedChange?: (speed:number)=>void;\n  onZoomChange?: (zoom:number)=>void;\n  onParamsChange?: (patch:Partial<AtomicParams>)=>void;\n  controls?: {run:()=>void;pause:()=>void;reset:()=>void};\n  interactive?: boolean;\n  onTick?: (stats: { \n    energy: number; \n    radius: number; \n    velocity: number; \n    n: number; \n    wavelength: number; \n    shellConfig: string \n  }) => void;\n}\n\nexport function AtomicModelsCanvas({ params, isRunning, isPaused, onTick, onModelChange, onSpeedChange, onZoomChange, onParamsChange, controls, interactive=true }: Props) {\n  const [viewReset,setViewReset]=useState(0);\n  const canvasPan=useRef({x:0,y:0});\n  const canvasDrag=useRef<{x:number;y:number;pan:{x:number;y:number}}|null>(null);\n  const canvasRef = useRef<HTMLCanvasElement | null>(null);\n  const wrapRef = useRef<HTMLDivElement | null>(null);\n  const rafRef = useRef<number>(0);\n  const lastFrameRef = useRef<number | null>(null);\n  const wallFrameRef=useRef<number|null>(null);\n  const wallDeltaRef=useRef(0);\n  const timeRef = useRef(0);\n  const lastTickRef = useRef(0);\n  const propsRef = useRef({ params, isRunning, isPaused, onTick });\n  propsRef.current = { params, isRunning, isPaused, onTick };\n\n  const thomsonRef = useRef<ThomsonElectron[]>([]);\n  const scatterRef = useRef<ScatteringParticle[]>([]);\n  const orbitalGridRef = useRef<{ x: number; z: number; prob: number }[][] | null>(null);\n  const orbitalCacheKeyRef = useRef('');\n  const quantumPulseRef = useRef(0);\n\n  const getFont = () => 'system-ui, sans-serif';\n\n  const resize = useCallback(() => {\n    const canvas = canvasRef.current;\n    const wrap = wrapRef.current;\n    if (!canvas || !wrap) return;\n    const dpr = window.devicePixelRatio || 1;\n    const rect = wrap.getBoundingClientRect();\n    const w = Math.floor(rect.width);\n    const h = Math.floor(rect.height);\n    if (canvas.width !== w * dpr || canvas.height !== h * dpr) {\n      canvas.width = w * dpr;\n      canvas.height = h * dpr;\n    }\n    canvas.style.width = w + 'px';\n    canvas.style.height = h + 'px';\n    const ctx = canvas.getContext('2d');\n    if (ctx) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  }, []);\n\n  const drawThomson=useCallback((ctx:CanvasRenderingContext2D,cx:number,cy:number,w:number,h:number,dt:number,p:AtomicParams)=>{\n    const r=Math.max(15,Math.min(w-44,h-40)*.43);\n    const pudding=ctx.createRadialGradient(cx-r*.3,cy-r*.35,r*.05,cx,cy,r);\n    pudding.addColorStop(0,'#fff1d6');pudding.addColorStop(.55,'#fda4af');pudding.addColorStop(1,'#e11d48');\n    ctx.fillStyle=pudding;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();\n    ctx.strokeStyle='#9f1239';ctx.lineWidth=2.5;ctx.stroke();\n    // Plus signs are symbols for a continuous positive medium, not protons.\n    ctx.save();ctx.beginPath();ctx.arc(cx,cy,r-3,0,Math.PI*2);ctx.clip();\n    ctx.strokeStyle='#9f1239';ctx.lineWidth=1.6;\n    const spacing=Math.max(18,r/3.5);\n    for(let x=-r;x<=r;x+=spacing)for(let y=-r;y<=r;y+=spacing){if(x*x+y*y>r*r*.92)continue;const px=cx+x,py=cy+y;ctx.beginPath();ctx.moveTo(px-4,py);ctx.lineTo(px+4,py);ctx.moveTo(px,py-4);ctx.lineTo(px,py+4);ctx.stroke();}\n    if(p.showElectrons){\n      const count=Math.max(1,Math.min(92,Math.round(p.protonCount||1)));\n      const plums=Array.from({length:count},(_,i)=>{const a=i*Math.PI*(3-Math.sqrt(5)),d=count===1?0:.82*Math.sqrt((i+.5)/count);return [Math.cos(a)*d,Math.sin(a)*d];});\n      plums.forEach(([x,y],i)=>{const oscillation=Math.sin(timeRef.current*1.2+i)*.012*r,ex=cx+x*r+oscillation,ey=cy+y*r;\n        const radius=Math.max(2.5,Math.min(13,r*.075,r*.48/Math.sqrt(count)));ctx.fillStyle='#1e40af';ctx.strokeStyle='#eff6ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(ex,ey,radius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(ex-radius*.4,ey);ctx.lineTo(ex+radius*.4,ey);ctx.stroke();});\n    }\n    ctx.restore();\n  },[]);\n\n  const drawRutherford = useCallback((ctx: CanvasRenderingContext2D, cx: number, cy: number, w: number, h: number, dt: number, p: AtomicParams) => {\n    const scale = Math.min(w-48, h-70) * 0.40;\n    const Z = p.protonCount || 79;\n    const A = Z + (p.neutronCount || 0);\n\n    if (p.showNucleus) {\n      const nuclearFm = 1.2 * Math.pow(A, 1 / 3);\n      const nr = Math.max(6, scale * 0.018 * Math.pow(A, 1 / 3));\n\n      // Coulomb field halo\n      const fieldR = nr * (3 + Math.log10(Math.max(Z, 1)));\n      const fieldGrad = ctx.createRadialGradient(cx, cy, nr, cx, cy, fieldR);\n      fieldGrad.addColorStop(0, `rgba(251,191,36,${0.08 + Z / 2000})`);\n      fieldGrad.addColorStop(0.6, 'rgba(251,191,36,0.03)');\n      fieldGrad.addColorStop(1, 'rgba(251,191,36,0)');\n      ctx.fillStyle = fieldGrad;\n      ctx.beginPath(); \n      ctx.arc(cx, cy, fieldR, 0, Math.PI * 2); \n      ctx.fill();\n\n      // Dense core\n      const coreGlow = ctx.createRadialGradient(cx, cy, 0, cx, cy, nr * 2.5);\n      coreGlow.addColorStop(0, 'rgba(255,255,255,0.95)');\n      coreGlow.addColorStop(0.25, 'rgba(251,191,36,0.85)');\n      coreGlow.addColorStop(0.7, 'rgba(245,158,11,0.35)');\n      coreGlow.addColorStop(1, 'rgba(245,158,11,0)');\n      ctx.fillStyle = coreGlow;\n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr * 2.5, 0, Math.PI * 2); \n      ctx.fill();\n\n      ctx.fillStyle = '#b45309';\n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr, 0, Math.PI * 2); \n      ctx.fill();\n\n      // Hard-sphere rim\n      ctx.strokeStyle = 'rgba(255,255,255,0.45)';\n      ctx.lineWidth = 1.5;\n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr, 0, Math.PI * 2); \n      ctx.stroke();\n\n      if (p.showLabels) {\n        ctx.fillStyle = '#b45309'; \n        ctx.font = 'bold 13px ' + getFont(); \n        ctx.textAlign = 'center';\n        ctx.fillText(`Nucleus  (${A}, ${Z})`, cx, cy + nr + 20);\n        ctx.fillStyle = '#92400e'; \n        ctx.font = '11px ' + getFont();\n        ctx.fillText(`r ≈ ${nuclearFm.toFixed(1)} fm`, cx, cy + nr + 36);\n      }\n    }\n\n    // Alpha spawn / update\n    if (dt > 0 && propsRef.current.isRunning && !propsRef.current.isPaused) {\n      if (Math.random() < 0.04 * p.speed) {\n        const b = (Math.random() - 0.5) * 400;\n        scatterRef.current.push(createAlphaParticle(b, p.alphaEnergy || 5));\n      }\n      scatterRef.current = scatterRef.current\n        .map(part => updateAlphaParticle(part, dt, p.protonCount))\n        .filter(part => part.active);\n    }\n\n    let recoilIntensity = 0;\n\n    scatterRef.current.forEach(part => {\n      const px = cx + part.x * scale * 0.0018;\n      const py = cy + part.y * scale * 0.0018;\n      const dx = px - cx;\n      const dy = py - cy;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n\n      if (part.active && dist < scale * 0.08) {\n        recoilIntensity = Math.max(recoilIntensity, 1 - dist / (scale * 0.08));\n      }\n\n      if (part.trail.length > 1) {\n        ctx.strokeStyle = 'rgba(190,18,60,0.7)'; \n        ctx.lineWidth = 1.5; \n        ctx.beginPath();\n        part.trail.forEach((pt, i) => {\n          const tx = cx + pt.x * scale * 0.0018;\n          const ty = cy + pt.y * scale * 0.0018;\n          if (i === 0) ctx.moveTo(tx, ty); else ctx.lineTo(tx, ty);\n        });\n        ctx.stroke();\n      }\n\n      const glow = ctx.createRadialGradient(px, py, 0, px, py, 10);\n      glow.addColorStop(0, 'rgba(244,63,94,0.6)'); \n      glow.addColorStop(1, 'rgba(244,63,94,0)');\n      ctx.fillStyle = glow; \n      ctx.beginPath(); \n      ctx.arc(px, py, 10, 0, Math.PI * 2); \n      ctx.fill();\n      ctx.fillStyle = '#f43f5e'; \n      ctx.beginPath(); \n      ctx.arc(px, py, 4, 0, Math.PI * 2); \n      ctx.fill();\n    });\n\n    // Recoil flash\n    if (recoilIntensity > 0) {\n      const flashNr = Math.max(6, scale * 0.018 * Math.pow(A, 1 / 3));\n      const flashR = flashNr * 5;\n      const flashGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, flashR);\n      flashGrad.addColorStop(0, `rgba(255,255,255,${recoilIntensity * 0.35})`);\n      flashGrad.addColorStop(0.4, `rgba(251,191,36,${recoilIntensity * 0.2})`);\n      flashGrad.addColorStop(1, 'rgba(251,191,36,0)');\n      ctx.fillStyle = flashGrad;\n      ctx.globalCompositeOperation = 'screen';\n      ctx.beginPath(); ctx.arc(cx, cy, flashR, 0, Math.PI * 2); ctx.fill();\n      ctx.globalCompositeOperation = 'source-over';\n    }\n\n  }, []);\n\n  const drawQuantum = useCallback((ctx: CanvasRenderingContext2D, cx: number, cy: number, w: number, h: number, dt: number, p: AtomicParams) => {\n    const scale = Math.min(w-48, h-70) * 0.32;\n    const n = p.nQuantum || 1, l = p.lQuantum || 0, m = p.mQuantum || 0, Z = p.protonCount || 1;\n    quantumPulseRef.current += dt * p.speed * 1.5;\n    if (p.showNucleus) {\n      const nr = 6, ng = ctx.createRadialGradient(cx, cy, 0, cx, cy, nr * 3);\n      ng.addColorStop(0, 'rgba(251,191,36,1)'); \n      ng.addColorStop(1, 'rgba(251,191,36,0)');\n      ctx.fillStyle = ng; \n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr * 3, 0, Math.PI * 2); \n      ctx.fill();\n      ctx.fillStyle = '#b45309'; \n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr, 0, Math.PI * 2); \n      ctx.fill();\n      if (p.showLabels) { \n        ctx.fillStyle = '#b45309'; \n        ctx.font = 'bold 12px ' + getFont();\n        ctx.textAlign = 'center'; \n        ctx.fillText(`Z=${Z}`, cx, cy + nr + 18); \n      }\n    }\n    if (p.showProbability) {\n      const cacheKey = `${n},${l},${m},${scale}`;\n      if (orbitalCacheKeyRef.current !== cacheKey) { \n        orbitalGridRef.current = generateOrbitalSlice(n, l, m, 60); \n        orbitalCacheKeyRef.current = cacheKey; \n      }\n      const grid = orbitalGridRef.current;\n      if (grid) {\n        let maxP = 0; \n        grid.forEach(row => row.forEach(pt => { if (pt.prob > maxP) maxP = pt.prob; }));\n        const cellW = (scale * 2.6) / grid[0].length, cellH = (scale * 2.6) / grid.length;\n        const pulse = 0.7 + 0.3 * Math.sin(quantumPulseRef.current);\n        grid.forEach((row, ri) => { row.forEach((pt, ci) => { const prob = pt.prob / (maxP || 1); \n          if (prob < 0.02) return; \n          const px = cx + (pt.x / (10 * n)) * scale * 1.3, py = cy - (pt.z / (10 * n)) * scale * 1.3; \n          const alpha = Math.min(0.65, prob * 2.5 * pulse); \n          const hue = 200 + prob * 100 + Math.sin(quantumPulseRef.current + ci * 0.1) * 15; \n          ctx.fillStyle = `hsla(${hue}, 85%, 38%, ${alpha})`; \n          ctx.fillRect(px - cellW / 2, py - cellH / 2, cellW + 1, cellH + 1); }); \n        });\n        const scanY = cy - scale * 1.3 + ((Math.sin(quantumPulseRef.current * 0.5) * 0.5 + 0.5) * scale * 2.6);\n        ctx.strokeStyle = 'rgba(255,255,255,0.12)'; \n        ctx.lineWidth = 1; \n        ctx.beginPath(); \n        ctx.moveTo(cx - scale * 1.3, scanY); \n        ctx.lineTo(cx + scale * 1.3, scanY); \n        ctx.stroke();\n      }\n    }\n    if (onTick) { const now = performance.now(); \n      if (now - lastTickRef.current > 80) { \n        lastTickRef.current = now; onTick({ energy: bohrEnergy(n, Z), radius: bohrRadius(n, Z), velocity: 0, n, wavelength: 0, shellConfig: `${n}${['s','p','d','f'][l] || '?'}` });\n      } }\n  }, [onTick]);\n\n  const drawLoop = useCallback((timestamp?: number) => {\n    const canvas = canvasRef.current, wrap = wrapRef.current;\n    if (!canvas || !wrap) return;\n    const ctx = canvas.getContext('2d');\n    if (!ctx) return;\n    const s = propsRef.current, p = s.params;\n    resize();\n    const rect = wrap.getBoundingClientRect(), w = rect.width, h = rect.height;\n    if(w<1||h<1){rafRef.current=requestAnimationFrame(drawLoop);return;}\n    wallDeltaRef.current=timestamp===undefined?0:Math.max(0,Math.min(.05,(timestamp-(wallFrameRef.current??timestamp))/1000));wallFrameRef.current=timestamp??null;\n    let dt = 0;\n    if (s.isRunning && !s.isPaused && timestamp !== undefined) { if (lastFrameRef.current !== null) dt = Math.min((timestamp - lastFrameRef.current) / 1000, 0.05); \n      lastFrameRef.current = timestamp; } else { lastFrameRef.current = timestamp ?? null; }\n    if (dt > 0) timeRef.current += dt * p.speed;\n    const t = timeRef.current;\n    ctx.clearRect(0, 0, w, h); \n    ctx.fillStyle = '#f8fafc'; \n    ctx.fillRect(0, 0, w, h);\n\n    const cx = w / 2, cy = h / 2;\n    const magnification=viewZoom(p.zoom),drawingParams={...p,zoom:1};\n    ctx.save();ctx.translate(cx+canvasPan.current.x,cy+canvasPan.current.y);ctx.scale(magnification,magnification);ctx.translate(-cx,-cy);\n    switch (p.model) { case 'thomson': drawThomson(ctx, cx, cy, w, h, dt, drawingParams); \n      break; \n      case 'rutherford': drawRutherford(ctx, cx, cy, w, h, dt, drawingParams); \n      break; \n      case 'bohr': break;\n      case 'quantum': drawQuantum(ctx, cx, cy, w, h, dt, drawingParams); \n      break; \n      }\n    ctx.restore();\n    rafRef.current = requestAnimationFrame(drawLoop);\n  }, [resize, drawThomson, drawRutherford, drawQuantum]);\n\n  useEffect(() => { resize(); \n    rafRef.current = requestAnimationFrame(drawLoop); \n    const observer=new ResizeObserver(resize);if(wrapRef.current)observer.observe(wrapRef.current);\n    window.addEventListener('resize', resize); \n    return () => { observer.disconnect();cancelAnimationFrame(rafRef.current); \n      window.removeEventListener('resize', resize); \n    }; \n  }, [drawLoop, resize, params.model]);\n\n  const notes:Record<AtomicModel,{title:string;description:string;legend:string}>= {\n    thomson:{title:'Thomson · plum-pudding atom',description:'The pink pudding is a continuous sphere of positive charge. Blue negative electrons are the embedded plums. The + symbols mark the positive medium, not separate protons; this model has no nucleus.',legend:'Pink pudding: distributed positive charge · Blue plums: negative electrons'},\n    rutherford:{title:'Rutherford · nuclear scattering',description:'Most alpha particles pass through empty space; close approaches to the positively charged nucleus produce stronger deflections. Sizes are exaggerated.',legend:'Amber: nucleus · Rose trails: alpha particles'},\n    bohr:{title:'Bohr · quantised states',description:'A one-electron, hydrogen-like model. The electron absorbs energy to reach a higher n and emits a photon when it falls to a lower n. Jumps and shell spacing are schematic.',legend:'Blue: electron / occupied orbit · Amber: absorption · Violet: emission'},\n    quantum:{title:'Quantum · probability density',description:'Colour intensity represents the relative electron probability density in a 2D orbital slice. An orbital is not an electron path.',legend:'Darker colour: greater relative probability · Amber: nucleus'},\n  };\n  const note=notes[params.model];\n  const n=params.nQuantum||1,l=params.lQuantum||0;\n  const radial=Array.from({length:81},(_,i)=>{const r=i/80*10*n;return{r,d:radialDistribution(n,l,r)};});\n  const maxD=Math.max(...radial.map(p=>p.d),1e-12);\n  return <div className=\"af-atomic-view\" data-model={params.model}>\n    <header className=\"af-atomic-toolbar\"><strong>Atomic laboratory</strong>\n      {onModelChange&&interactive?<label>Model<select aria-label=\"Atomic model\" value={params.model} onChange={e=>{onModelChange(e.target.value as AtomicModel);onZoomChange?.(1);canvasPan.current={x:0,y:0};setViewReset(v=>v+1);}}><option value=\"thomson\">Thomson · plum pudding</option><option value=\"rutherford\">Rutherford · scattering</option><option value=\"bohr\">Bohr · radiation & states</option><option value=\"quantum\">Quantum · probability</option></select></label>:<span>{note.title}</span>}\n      {onSpeedChange&&interactive&&<label>Speed<select aria-label=\"Lesson speed\" value={params.speed} onChange={e=>onSpeedChange(Number(e.target.value))}>{Array.from(new Set([0,.5,1,1.5,2,3,params.speed])).sort((a,b)=>a-b).map(v=><option key={v} value={v}>{v}×</option>)}</select></label>}\n      {interactive&&onParamsChange&&(params.model==='bohr'||params.model==='quantum'||params.model==='thomson')&&<label>Z<input aria-label=\"Nuclear charge Z\" type=\"number\" min=\"1\" max=\"92\" value={params.protonCount} onChange={e=>{const v=Number(e.target.value);if(Number.isInteger(v)&&v>=1&&v<=92)onParamsChange({protonCount:v});}}/></label>}\n      {interactive&&onParamsChange&&params.model==='quantum'&&<div className=\"af-quantum-controls\" aria-label=\"Quantum parameters\">{(['n','l','m'] as const).map(key=>{const value=key==='n'?n:key==='l'?l:params.mQuantum||0;const values=key==='n'?[1,2,3,4]:key==='l'?Array.from({length:n},(_,i)=>i):Array.from({length:2*l+1},(_,i)=>i-l);return <label key={key}>{key}<select aria-label={`Quantum ${key}`} value={value} onChange={e=>{const v=Number(e.target.value);if(key==='n')onParamsChange({nQuantum:v,lQuantum:Math.min(l,v-1),mQuantum:Math.max(-Math.min(l,v-1),Math.min(params.mQuantum||0,Math.min(l,v-1)))});else if(key==='l')onParamsChange({lQuantum:v,mQuantum:Math.max(-v,Math.min(params.mQuantum||0,v))});else onParamsChange({mQuantum:v});}}>{values.map(v=><option key={v} value={v}>{v}</option>)}</select></label>;})}<span>{n}{['s','p','d','f'][l]} · {n-l-1} radial / {l} angular nodes · E={bohrEnergy(n,params.protonCount).toFixed(3)} eV</span></div>}\n      {interactive&&onParamsChange&&params.model==='bohr'&&params.showSpin&&<label title=\"Spin projection along the chosen vertical axis; not literal rotation\">Spin<select aria-label=\"Electron spin projection\" value={params.spinProjection??0.5} onChange={e=>onParamsChange({spinProjection:Number(e.target.value)===-0.5?-0.5:0.5})}><option value=\"0.5\">↑ mₛ = +½</option><option value=\"-0.5\">↓ mₛ = −½</option></select></label>}\n      {interactive&&onZoomChange&&<label className=\"af-atomic-zoom\">Zoom<input aria-label=\"View zoom\" type=\"range\" min=\"0.3\" max=\"3\" step=\"0.1\" value={params.zoom} onChange={e=>onZoomChange(Number(e.target.value))}/><output>{viewZoom(params.zoom).toFixed(1)}×</output><button type=\"button\" onClick={()=>{onZoomChange(1);canvasPan.current={x:0,y:0};setViewReset(v=>v+1);}}>Fit</button></label>}\n      {interactive&&onParamsChange&&params.model==='bohr'&&<><label title=\"Chosen screening constant; Zeff=Z−σ. Hydrogenic approximation.\">σ<input aria-label=\"Screening constant\" type=\"number\" min=\"0\" max={Math.max(0,params.protonCount-1)} step=\"0.1\" disabled={params.protonCount<=1} value={params.screening??0} onChange={e=>{const v=Number(e.target.value);if(Number.isFinite(v)&&v>=0&&v<=params.protonCount-1)onParamsChange({screening:v});}}/></label>{params.showZeeman&&<label>B (T)<input aria-label=\"Magnetic field B\" type=\"range\" min=\"0\" max=\"5\" step=\"0.1\" value={params.magneticField} onChange={e=>onParamsChange({magneticField:Number(e.target.value)})}/><output>{params.magneticField.toFixed(1)}</output></label>}</>}\n      {interactive&&onParamsChange&&<details className=\"af-atomic-display\"><summary>Physics options</summary><div>{([['showOrbits','Orbits'],['showElectrons','Electrons'],['showNucleus','Nucleus'],['showEnergyLevels','Energy levels'],['showLabels','Labels'],...(params.model==='bohr'?[['showSpectrum','Spectrum'],['showSpin','Electron spin'],['showFineStructure','Fine structure'],['showZeeman','Zeeman effect']]:[]),...(params.model==='quantum'?[['showProbability','Probability cloud']]:[])] as [keyof AtomicParams,string][]).map(([key,label])=><label key={key}><input type=\"checkbox\" checked={!!params[key]} onChange={e=>onParamsChange({[key]:e.target.checked})}/>{label}</label>)}</div></details>}\n      {params.model!=='bohr'&&controls&&interactive&&<div className=\"af-atomic-playback\"><button type=\"button\" onClick={isRunning?controls.pause:controls.run}>{!isRunning?'Run':isPaused?'Resume':'Pause'}</button><button type=\"button\" onClick={controls.reset}>Reset</button></div>}\n    </header>\n    {params.model==='bohr'?<BohrRadiationLab params={params} onTick={onTick} interactive={interactive} viewReset={viewReset} isRunning={isRunning} isPaused={isPaused} controls={controls}/>:<>\n    <div className=\"af-atomic-layout\">\n      <div className=\"af-atomic-scene\" ref={wrapRef}>\n        <canvas ref={canvasRef} onPointerDown={e=>{canvasDrag.current={x:e.clientX,y:e.clientY,pan:{...canvasPan.current}};e.currentTarget.setPointerCapture(e.pointerId);}} onPointerMove={e=>{const d=canvasDrag.current;if(d)canvasPan.current={x:d.pan.x+e.clientX-d.x,y:d.pan.y+e.clientY-d.y};}} onPointerUp={()=>{canvasDrag.current=null;}} onPointerCancel={()=>{canvasDrag.current=null;}} role=\"img\" aria-label={`${note.title}. ${note.legend}.`} />\n      </div>\n    </div>\n    {params.showLabels&&<section className=\"af-atomic-notes\" aria-label=\"Model explanation\"><h3>{note.title}</h3><p>{note.description}</p><p className=\"af-atomic-legend\">{note.legend}</p><p className=\"af-atomic-caption\">Diagram sizes are schematic. Zoom magnifies the view; drag to pan and use Fit to restore framing.</p></section>}\n    {params.model==='quantum'&&params.showProbability&&<section className=\"af-atomic-notes\"><h3>Radial probability · n = {n}, l = {l}</h3><svg viewBox=\"0 0 420 130\" role=\"img\" aria-label=\"Relative radial probability distribution\" className=\"af-atomic-radial\"><path d=\"M35 15V105H400\" fill=\"none\" stroke=\"#64748b\"/><path d={radial.map((p,i)=>`${i?'L':'M'}${35+p.r/(10*n)*365} ${105-p.d/maxD*80}`).join(' ')} fill=\"none\" stroke=\"#4f46e5\" strokeWidth=\"3\"/><text x=\"38\" y=\"125\" fontSize=\"12\">0</text><text x=\"285\" y=\"125\" fontSize=\"12\">r / a₀ → {10*n}</text></svg></section>}\n    </>}\n  </div>;\n}\n", "src/app/simulations/atomic-models/page.tsx": "'use client';\nimport {AtomicModelLearning} from '@/components/simulation/AtomicModelLearning';\nimport {effectiveCharge,fineSeparation} from '@/lib/physics/atomicExtensions';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useMemo, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { AtomicModelsCanvas } from '@/components/simulation/AtomicModelsCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport {\n  ATOMIC_PRESETS, AtomicParams, AtomicModel,\n  generateHydrogenSpectrum,\n  bohrEnergy, bohrRadius, bohrVelocity,\n  validQuantumNumbers, possibleLValues, possibleMValues,\n  getShellCapacity,\n} from '@/lib/physics/atomicModels';\n\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700',\n  NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700',\n  SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n  'A-Level': 'bg-cyan-100 text-cyan-700',\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function AtomicModelsPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB', 'A-Level']);\n  const [mobileControlsOpen, setMobileControlsOpen] = useState(false);\n\n  const [model, setModel] = useState<AtomicModel>('thomson');\n  const [speed, setSpeed] = useState(1);\n  const [zoom, setZoom] = useState(1);\n  const [showOrbits, setShowOrbits] = useState(true);\n  const [showNucleus, setShowNucleus] = useState(true);\n  const [showElectrons, setShowElectrons] = useState(true);\n  const [showProbability, setShowProbability] = useState(true);\n  const [showEnergyLevels, setShowEnergyLevels] = useState(true);\n  const [showSpectrum, setShowSpectrum] = useState(true);\n  const [showLabels, setShowLabels] = useState(true);\n  const [spinProjection,setSpinProjection] = useState<0.5|-0.5>(0.5);\n  const [showSpin, setShowSpin] = useState(false);\n  const [showFineStructure, setShowFineStructure] = useState(false);\n  const [showZeeman, setShowZeeman] = useState(false);\n  const [magneticField, setMagneticField] = useState(0);\n  const [nQuantum, setNQuantum] = useState(1);\n  const [lQuantum, setLQuantum] = useState(0);\n  const [mQuantum, setMQuantum] = useState(0);\n  const [protonCount, setProtonCount] = useState(1);\n  const [neutronCount, setNeutronCount] = useState(0);\n  const [electronCount, setElectronCount] = useState(1);\n  const [alphaEnergy, setAlphaEnergy] = useState(5);\n\n  const [screening,setScreening]=useState(0);\n  useEffect(()=>{setScreening(s=>Math.min(s,Math.max(0,protonCount-1)));},[protonCount]);\n  const params: AtomicParams = {\n    model, speed, zoom, screening:Math.min(screening,Math.max(0,protonCount-1)), showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, spinProjection, showFineStructure,\n    showZeeman, magneticField, nQuantum, lQuantum, mQuantum,\n    protonCount, neutronCount, electronCount:model==='thomson'?protonCount:electronCount, alphaEnergy,\n  };\n\n  const [liveStats, setLiveStats] = useState({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: typeof liveStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const applyPreset = useCallback((presetIdx: number) => {\n    const preset = ATOMIC_PRESETS[presetIdx];\n    if (!preset) return;\n    setModel(preset.model);\n    const pp = preset.params;\n    setScreening(pp.screening??0);\n    if (pp.speed !== undefined) setSpeed(pp.speed);\n    setZoom(1);\n    if (pp.showOrbits !== undefined) setShowOrbits(pp.showOrbits);\n    if (pp.showNucleus !== undefined) setShowNucleus(pp.showNucleus);\n    if (pp.showElectrons !== undefined) setShowElectrons(pp.showElectrons);\n    if (pp.showProbability !== undefined) setShowProbability(pp.showProbability);\n    if (pp.showEnergyLevels !== undefined) setShowEnergyLevels(pp.showEnergyLevels);\n    if (pp.showSpectrum !== undefined) setShowSpectrum(pp.showSpectrum);\n    if (pp.showLabels !== undefined) setShowLabels(pp.showLabels);\n    if (pp.showSpin !== undefined) setShowSpin(pp.showSpin);\n    if (pp.showFineStructure !== undefined) setShowFineStructure(pp.showFineStructure);\n    if (pp.showZeeman !== undefined) setShowZeeman(pp.showZeeman);\n    if (pp.magneticField !== undefined) setMagneticField(pp.magneticField);\n    if (pp.nQuantum !== undefined) setNQuantum(pp.nQuantum);\n    if (pp.lQuantum !== undefined) setLQuantum(pp.lQuantum);\n    if (pp.mQuantum !== undefined) setMQuantum(pp.mQuantum);\n    if (pp.protonCount !== undefined) setProtonCount(pp.protonCount);\n    if (pp.neutronCount !== undefined) setNeutronCount(pp.neutronCount);\n    if (pp.electronCount !== undefined) setElectronCount(pp.electronCount);\n    if (pp.alphaEnergy !== undefined) setAlphaEnergy(pp.alphaEnergy);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  useEffect(() => {\n    if (!validQuantumNumbers(nQuantum, lQuantum, mQuantum)) {\n      const validL = possibleLValues(nQuantum);\n      if (!validL.includes(lQuantum)) { setLQuantum(validL[0]); setMQuantum(0); }\n    }\n  }, [nQuantum]);\n\n  useEffect(() => {\n    const validM = possibleMValues(lQuantum);\n    if (!validM.includes(mQuantum)) setMQuantum(validM[0]);\n  }, [lQuantum]);\n\n  const spectrum = useMemo(() => generateHydrogenSpectrum(7), []);\n  const modelLabels: Record<AtomicModel, string> = { thomson: 'Thomson (1897)', rutherford: 'Rutherford (1911)', bohr: 'Bohr (1913)', quantum: 'Quantum (1926)' };\n\n  useTopicPreset(\"simulations-atomic-models\", { \"speed\": setSpeed,\n    \"zoom\": setZoom,\n    \"protonCount\": setProtonCount,\n    \"neutronCount\": setNeutronCount,\n    \"alphaEnergy\": setAlphaEnergy,\n    \"magneticField\": setMagneticField,\n    \"nQuantum\": setNQuantum }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Atomic Physics — From Plum Pudding to Quantum Field Theory</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Atomic Models</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {Object.keys(CC).map(c => (\n                  <button key={c} onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'}`}>\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div data-atomic-model={model} className=\"af-atomic-page mx-auto max-w-[100rem] px-3 sm:px-4 py-2 space-y-2\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Thomson → Rutherford → Bohr → Schrödinger</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">Eₙ = -13.6 Z²/n² eV</span>\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => (\n              <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n                className={`shrink-0 rounded-xl border px-4 py-2 text-left hover:shadow-sm transition min-w-[110px] ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-200'}`}>\n                <p className=\"text-xs font-medium\">{modelLabels[m]}</p>\n              </button>\n            ))}\n          </div>\n\n          <details className=\"af-atomic-presets\"><summary>Presets · choose a demonstration</summary><div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {ATOMIC_PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(i)}\n                className=\"shrink-0 rounded-xl border border-gray-200 bg-white px-3 py-2 text-left hover:border-indigo-300 hover:shadow-sm transition min-w-[160px]\">\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div></details>\n\n          <div className=\"grid grid-cols-1 gap-2\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <AtomicModelsCanvas key={resetKey} params={params} onZoomChange={setZoom} onParamsChange={patch=>{if(patch.protonCount!==undefined)setProtonCount(patch.protonCount);if(patch.showOrbits!==undefined)setShowOrbits(patch.showOrbits);if(patch.showElectrons!==undefined)setShowElectrons(patch.showElectrons);if(patch.showNucleus!==undefined)setShowNucleus(patch.showNucleus);if(patch.showEnergyLevels!==undefined)setShowEnergyLevels(patch.showEnergyLevels);if(patch.showLabels!==undefined)setShowLabels(patch.showLabels);if(patch.showSpin!==undefined)setShowSpin(patch.showSpin);if(patch.spinProjection!==undefined)setSpinProjection(patch.spinProjection);if(patch.showSpectrum!==undefined)setShowSpectrum(patch.showSpectrum);if(patch.showFineStructure!==undefined)setShowFineStructure(patch.showFineStructure);if(patch.showZeeman!==undefined)setShowZeeman(patch.showZeeman);if(patch.magneticField!==undefined)setMagneticField(patch.magneticField);if(patch.screening!==undefined)setScreening(patch.screening);if(patch.showProbability!==undefined)setShowProbability(patch.showProbability);if(patch.nQuantum!==undefined)setNQuantum(patch.nQuantum);if(patch.lQuantum!==undefined)setLQuantum(patch.lQuantum);if(patch.mQuantum!==undefined)setMQuantum(patch.mQuantum);}} isRunning={isRunning} isPaused={isPaused} onModelChange={setModel} onSpeedChange={setSpeed} controls={{run:()=>{setIsRunning(true);setIsPaused(false);},pause:()=>setIsPaused(v=>!v),reset}} onTick={handleTick} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/atomic-models\" title=\"Atomic Models\"\n                  params={{ model, speed, zoom, S:screening, orbits: showOrbits ? 1 : 0, nucleus: showNucleus ? 1 : 0, electrons: showElectrons ? 1 : 0, prob: showProbability ? 1 : 0, levels: showEnergyLevels ? 1 : 0, spectrum: showSpectrum ? 1 : 0, labels: showLabels ? 1 : 0, spin: showSpin ? 1 : 0, ms:spinProjection, fs: showFineStructure ? 1 : 0, zeeman: showZeeman ? 1 : 0, B: magneticField, n: nQuantum, l: lQuantum, m: mQuantum, Z: protonCount, N: neutronCount, e: model==='thomson'?protonCount:electronCount, alphaE: alphaEnergy }} />\n              </div>\n\n              {/* Mobile controls toggle */}\n              <div className=\"af-atomic-below-parameters\"><button onClick={() => setMobileControlsOpen(o => !o)} className=\"lg:hidden w-full py-2 text-sm font-medium rounded-xl border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 transition\">\n                {mobileControlsOpen ? 'Hide extra parameters ▲' : 'More parameters ▼'}\n              </button></div>\n\n              <div data-stage-role=\"inline-parameters\" className={`af-atomic-below-parameters rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4 ${mobileControlsOpen ? '' : 'hidden lg:block'}`}>\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">Display</p>\n                    <Slider label=\"Animation speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" note=\"Time evolution speed\" />\n                    <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" note=\"Magnification: drag the view to pan; Fit restores framing.\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Nucleus</p>\n                    <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" note=\"Atomic number\" />\n                    <Slider label=\"Neutrons N\" unit=\"\" value={neutronCount} min={0} max={150} step={1} set={setNeutronCount} color=\"#a78bfa\" note=\"Neutron number\" />\n                  </div>\n                </div>\n\n                {model === 'rutherford' && (\n                  <div className=\"border-t border-gray-100 pt-3\">\n                    <Slider label=\"α-particle energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" note=\"Kinetic energy of incoming α particles\" />\n                  </div>\n                )}\n\n                {model === 'bohr' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-emerald-600 uppercase tracking-wide\">Bohr Model Options</p>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showOrbits} onChange={e => setShowOrbits(e.target.checked)} className=\"rounded\" /> Show orbits</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showEnergyLevels} onChange={e => setShowEnergyLevels(e.target.checked)} className=\"rounded\" /> Energy levels</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpectrum} onChange={e => setShowSpectrum(e.target.checked)} className=\"rounded\" /> Spectrum bar</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpin} onChange={e => setShowSpin(e.target.checked)} className=\"rounded\" /> Show spin (↑ / ↓)</label>\n                    </div>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showFineStructure} onChange={e => setShowFineStructure(e.target.checked)} className=\"rounded\" /> Fine structure (j = l ± ½)</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showZeeman} onChange={e => setShowZeeman(e.target.checked)} className=\"rounded\" /> Zeeman effect</label>\n                    </div>\n                    {showZeeman && <Slider label=\"Magnetic field B\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" note=\"Tesla — splits degenerate levels\" />}\n                  </div>\n                )}\n\n                {model === 'quantum' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-purple-600 uppercase tracking-wide\">Quantum Numbers</p>\n                    <div className=\"grid grid-cols-3 gap-3\">\n                      <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" note=\"Principal quantum number\" />\n                      <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" note=\"Angular momentum (0=s,1=p,2=d,3=f)\" />\n                      <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" note=\"Magnetic quantum number\" />\n                    </div>\n                    <p className=\"text-[10px] text-gray-400\">Orbital: <span className=\"font-medium text-indigo-600\">{nQuantum}{['s','p','d','f'][lQuantum] || '?'}</span> — <span className=\"text-gray-500\">{lQuantum === 0 ? 'spherical, no angular nodes' : lQuantum === 1 ? 'dumbbell, 1 angular node' : lQuantum === 2 ? 'cloverleaf, 2 angular nodes' : lQuantum === 3 ? 'complex 8-lobed, 3 angular nodes' : 'higher orbital'}</span></p>\n                  </div>\n                )}\n\n                <div className=\"border-t border-gray-100 pt-3\">\n                  <p className=\"text-[10px] font-medium text-gray-500 uppercase tracking-wide mb-2\">Visibility</p>\n                  <div className=\"flex flex-wrap gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" /> Nucleus</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" /> Electrons</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" /> Probability cloud</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" /> Info labels</label>\n                  </div>\n                </div>\n              </div>\n            <div data-stage-role=\"parameters\" className=\"af-atomic-side-results space-y-2\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {model === 'bohr' && (\n                    <>\n                      <StatRow label=\"Energy Eₙ\" value={liveStats.energy.toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                      <StatRow label=\"Radius rₙ\" value={liveStats.radius.toFixed